def main():
    """Main extraction entry point."""
    print("=" * 70)
    print("Extract data to staging JSON")
    print("=" * 70)
    
    # Create staging directories
    for year in ["2024", "2025", "2026"]:
        staging_dir = os.path.join(STAGING_DIR, SCHOOL_ID, year)
        os.makedirs(staging_dir, exist_ok=True)
    
    # Extract enrollment plans
    print("\n[1/4] Extracting enrollment plans...")
    plans = extract_enrollment_plans()
    for year, data in plans.items():
        output_path = os.path.join(STAGING_DIR, SCHOOL_ID, year, "enrollment_plans.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump({
                "extracted_at": EXTRACTED_AT,
                "source_school_id": SCHOOL_ID,
                "source_year": year,
                "data": data,
            }, f, ensure_ascii=False, indent=2)
        print(f"  {year}: {len(data)} records → {output_path}")
    
    # Extract eligibility
    print("\n[2/4] Extracting eligibility...")
    elig = extract_eligibility()
    for year, data in elig.items():
        output_path = os.path.join(STAGING_DIR, SCHOOL_ID, year, "eligibility.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump({
                "extracted_at": EXTRACTED_AT,
                "source_school_id": SCHOOL_ID,
                "source_year": year,
                "data": data,
            }, f, ensure_ascii=False, indent=2)
        print(f"  {year}: {len(data)} records → {output_path}")
    
    # Extract exam subjects
    print("\n[3/4] Extracting exam subjects...")
    subj = extract_exam_subjects()
    for year, data in subj.items():
        output_path = os.path.join(STAGING_DIR, SCHOOL_ID, year, "exam_subjects.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump({
                "extracted_at": EXTRACTED_AT,
                "source_school_id": SCHOOL_ID,
                "source_year": year,
                "data": data,
            }, f, ensure_ascii=False, indent=2)
        print(f"  {year}: {len(data)} records → {output_path}")
    
    # Extract admission scores
    print("\n[4/4] Extracting admission scores...")
    scores = extract_admission_scores()
    for year, data in scores.items():
        output_path = os.path.join(STAGING_DIR, SCHOOL_ID, year, "admission_scores.json")
        with open(output_path, "w", encoding="utf-8") as f:
            json.dump({
                "extracted_at": EXTRACTED_AT,
                "source_school_id": SCHOOL_ID,
                "source_year": year,
                "data": data,
            }, f, ensure_ascii=False, indent=2)
        print(f"  {year}: {len(data)} records → {output_path}")
    
    print("\n" + "=" * 70)
    print("Extraction complete!")
    print("=" * 70)


if __name__ == "__main__":
    main()
